                if(d->err != nullptr)
                {
                    return;
                }

                // There was a match at the previous step, and the current match is
                // not better. Output the previous match.
                rec::AddMatch(gocpp::recv(d->tokens), uint32_t(prevLength - 3), uint32_t(prevOffset - minOffsetSize));

